function ed(a,b){let d=Array.from({length:a.length+1},(_,i)=>Array.from({length:b.length+1},(_,j)=>i===0?j:j===0?i:0));for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+Number(a[i-1]!==b[j-1]));return d[a.length][b.length]}
function osa(a,b){let d=Array.from({length:a.length+1},(_,i)=>Array.from({length:b.length+1},(_,j)=>i===0?j:j===0?i:0));for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++){d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+Number(a[i-1]!==b[j-1]));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])d[i][j]=Math.min(d[i][j],d[i-2][j-2]+1)}return d[a.length][b.length]}
function dl(a,b){let m=a.length,n=b.length,inf=m+n,H=Array.from({length:m+2},()=>Array(n+2).fill(0));H[0][0]=inf;for(let i=0;i<=m;i++){H[i+1][0]=inf;H[i+1][1]=i}for(let j=0;j<=n;j++){H[0][j+1]=inf;H[1][j+1]=j}let last=new Map();for(let i=1;i<=m;i++){let db=0;for(let j=1;j<=n;j++){let i1=last.get(b[j-1])??0,j1=db,cost=1;if(a[i-1]===b[j-1]){cost=0;db=j}H[i+1][j+1]=Math.min(H[i][j]+cost,H[i+1][j]+1,H[i][j+1]+1,H[i1][j1]+i-i1-1+1+j-j1-1)}last.set(a[i-1],i)}return H[m+1][n+1]}
function words(alphabet,max){let out=[""],level=[""];for(let n=1;n<=max;n++){level=level.flatMap(w=>[...alphabet].map(c=>w+c));out.push(...level)}return out}
function neighbors(x,alphabet){let out=new Set();for(let i=0;i<x.length;i++){out.add(x.slice(0,i)+x.slice(i+1));for(let c of alphabet)out.add(x.slice(0,i)+c+x.slice(i+1));if(i+1<x.length)out.add(x.slice(0,i)+x[i+1]+x[i]+x.slice(i+2))}for(let i=0;i<=x.length;i++)for(let c of alphabet)out.add(x.slice(0,i)+c+x.slice(i));out.delete(x);return out}
function bfs(x,alphabet,depth){let dist=new Map([[x,0]]),front=[x];for(let k=1;k<=depth;k++){let next=[];for(let v of front)for(let w of neighbors(v,alphabet)){if(!dist.has(w)){dist.set(w,k);next.push(w)}}front=next}return dist}
function grams(s,q){let p=new Map();for(let i=0;i+q<=s.length;i++){let g=s.slice(i,i+q);p.set(g,(p.get(g)??0)+1)}return p}
function gramDist(a,b,q){let x=grams(a,q),y=grams(b,q);return [...new Set([...x.keys(),...y.keys()])].reduce((t,g)=>t+Math.abs((x.get(g)??0)-(y.get(g)??0)),0)}
function run(){let checks={dl_oracle:0,qgram_bound:0},failures=[],cases=[];let w=words("abc",3);for(let a of w){let oracle=bfs(a,"abc",3);for(let b of w){checks.dl_oracle++;let actual=dl(a,b),expected=oracle.get(b);if(actual!==expected)failures.push({type:"DL",a,b,actual,expected})}}w=words("ab",6);for(let a of w)for(let b of w){let d=ed(a,b);for(let q=1;q<=4;q++){checks.qgram_bound++;let g=gramDist(a,b,q);if(g>2*q*d)failures.push({type:"qgram",a,b,q,g,d})}}for(let [a,b] of [["ca","abc"],["ba","ab"],["ab","acb"],["ba","acb"],["ab","ba"],["aaaa","aaa"],["a","b"]])cases.push({a,b,levenshtein:ed(a,b),osa:osa(a,b),damerau:dl(a,b),qgram2_l1:gramDist(a,b,2)});return {checks,total:checks.dl_oracle+checks.qgram_bound,failures,cases}}
console.log(JSON.stringify(run(),null,2));
